test('does not hang on negative size (nanoid)', () => {
  equal(nanoid(-1), '')
  equal(nanoid(-100), '')
})

test(`avoids pool pollution, infinite loop`, () => {
  nanoid(2.1)
  let second = nanoid()
  let third = nanoid()
  notEqual(second, third)
})

test('throws on negative or too big ID length', () => {
  throws(() => {
    nanoid(2147483648)
  }, /Wrong ID size|Invalid typed array length/)
  throws(() => {
    nanoid(-10)
  }, /Wrong ID size|Invalid typed array length/)
  let a = nanoid()
  let b = nanoid()
  notEqual(a, b)
})

test(`prevent collision with proxy number`, () => {
  let makeProxyNumberToReproducePreviousID = () => {
    let step = 0
    return {
      valueOf() {
        // "if (!pool || pool.length < bytes) {"
        if (step === 0) {
          step++
          return 0
        }
        // "} else if (poolOffset + bytes > pool.length) {"
        if (step === 1) {
          step++
          return -Infinity
        }
        // "poolOffset += bytes"
        if (step === 2) {
          step++
          return 0
        }

        return 21
      }
    }
  }

  let id1 = nanoid()
  let id2 = nanoid(makeProxyNumberToReproducePreviousID())
  notEqual(id1, id2)
})

